package com.projexa.coaching.academics.controller;
import com.projexa.coaching.academics.entity.Subject; import com.projexa.coaching.academics.service.SubjectService; import com.projexa.coaching.common.responses.ApiResponse; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/subjects") public class SubjectController { private final SubjectService service; public SubjectController(SubjectService service){this.service=service;} @GetMapping @PreAuthorize("hasAuthority('dashboard.read') or hasAuthority('settings.manage') or hasAuthority('students.read')") public ApiResponse<List<Subject>> list(){return ApiResponse.ok(service.list());} @GetMapping("/{id}") @PreAuthorize("hasAuthority('dashboard.read') or hasAuthority('settings.manage') or hasAuthority('students.read')") public ApiResponse<Subject> get(@PathVariable UUID id){return ApiResponse.ok(service.get(id));} @PostMapping @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.create')") public ApiResponse<Subject> create(@RequestBody Subject item){return ApiResponse.ok(service.create(item));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.update')") public ApiResponse<Subject> update(@PathVariable UUID id,@RequestBody Subject item){return ApiResponse.ok(service.update(id,item));} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.delete')") public ApiResponse<Void> delete(@PathVariable UUID id){service.delete(id);return ApiResponse.ok(null);} }